Example:
pipeline {
  agent any
  stages { stage('Build') { steps { sh 'make build' } } }
}

stage('Checks') {
  parallel {
    stage('Lint') { steps { sh 'make lint' } }
    stage('Test') { steps { sh 'make test' } }
  }
}

stage('Deploy Prod') {
  input message: 'Deploy to production?'
  steps { sh 'deploy.sh prod' }
}
